const state = { bootstrap: null, page: "home", activeSave: null, saveLoading: false, homeContext: null, homeContextError: null, artwork: {}, artworkUrls: new Set(), selectedArtworkTeam: null, selectedHomeTeam: null, history: [], savedReview: null, seasonLines: null, seasonLinesSave: null, seasonLinesError: null, toolSettings: new Map(), prepared: new Map(), commentaryReview: null, jerseyMode: "standard", jerseyPreviews: new Map(), jerseyView: "cards", equipmentPreviews: new Map(), equipmentView: "cards", equipmentWizard: new Map(), genericPreviews: new Map(), genericResultViews: new Map(), forceWinPreviews: new Map(), dealbreakerPreviews: new Map() };
const content = document.querySelector("#content");
let toolSettingsRestoreDepth = 0;
const escapeHtml = value => String(value ?? "").replace(/[&<>'"]/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[char]);
