    control.dataset.sessionRestored = "true";
    // Rendering a loading message triggers the restore observer too. No-op
    // restoration is not a user edit and must not cancel an in-flight tool.
    if (before !== JSON.stringify(valueOf(control))) control.dispatchEvent(new Event("change", { bubbles: true }));
