function multiSelectEmptyMeaning(id){if(/included|positions|classes|bodies|mapper-rule-teams|nil-teams|nil-players|nil-redshirts|^(?:commentary|boost)-(?:players|redshirt)$/.test(id))return"All";if(/excluded|skipped/.test(id))return"None";return"None";}
function updateMultiSelectCount(control){const label=document.querySelector(`[data-multi-label-for="${control.id}"]`);if(!label)return;const count=control.selectedOptions.length,total=control.options.length,base=label.dataset.baseLabel,empty=label.dataset.emptyMeaning;const text=count===total&&total>0?`${base} (All selected)`:count===0?`${base} (0 selected — ${empty})`:`${base} (${count} selected)`;if(label.textContent!==text)label.textContent=text;}
