function applyTeamLogoFallback(image) { if (!image?.matches?.("img[data-team-logo]") || image.dataset.fallbackApplied === "true") return; image.dataset.fallbackApplied = "true"; image.classList.add("team-logo-fallback"); image.src = teamLogoFallback; }
