function navigate(page) { if(state.saveLoading)return; captureToolSettings(); if (page !== "commentary-id" && state.page === "commentary-id" && !discardReviewAllowed()) return; if (page !== "commentary-id") state.commentaryReview = null;historyOpenRequest++;if(state.page==="saved-review"&&page!=="saved-review")releaseSavedReviewArtwork(); if(state.page === "history" || page === "history")historyFilters.page=0; state.page = page; document.querySelectorAll("[data-page]").forEach(node => node.classList.toggle("active", node.dataset.page === page)); render(); }
