    shell.querySelector(`[data-team-filter="${id}"]`)?.addEventListener("input", event => { const query = event.target.value.trim().toLowerCase(); shell.querySelectorAll(`[data-team-row="${id}"]`).forEach(row => { row.hidden = Boolean(query && !row.dataset.search.includes(query)); }); shell.querySelector(".team-picker-list").scrollTop = 0; });
    shell.querySelector(`[data-team-all="${id}"]`)?.addEventListener("click", () => { [...select.options].forEach(option => { option.selected = true; }); select.dispatchEvent(new Event("change", { bubbles: true })); });
    shell.querySelector(`[data-team-none="${id}"]`)?.addEventListener("click", () => { [...select.options].forEach(option => { option.selected = false; }); select.dispatchEvent(new Event("change", { bubbles: true })); });
