async function runTool(toolId, mode) { const runSave = state.activeSave?.path, runPage = state.page; const output = document.querySelector("#run-output"), previous = state.genericPreviews.get(toolId); const options = mode === "apply" ? { planId: previous?.planId } : collectOptions(toolId); if (mode === "apply" && (!options.planId || previous?.details?.canApply === false)) return; if (toolId === "roster-generator" && mode === "apply") { if (previous?.details?.canApply === false) return; if (!await appConfirm("Regenerate Selected Rosters?", `This replaces ${previous?.details?.totalPreviewRows ?? 0} players on ${(previous?.details?.teams ?? []).map(team => team.team).join(", ")}, including their existing original EA roster players. A backup is created first. Existing statistics and historical records are not reset. Test a copied dynasty in-game before using this on a long-running save.`, "Back Up & Regenerate")) return; if (state.page !== runPage || state.activeSave?.path !== runSave || state.genericPreviews.get(toolId) !== previous || !output.isConnected) return; options.confirmRegeneration = true; } const invalid = mode === "preview" ? validateOptions(toolId, options) : null; if (invalid) { toast(invalid); return; } if (mode === "preview") showStandardPreviewStage(true); document.querySelectorAll("#preview,#apply").forEach(button => button.disabled = true); output.innerHTML = `${toolLoading(`${mode === "preview" ? "Building preview…" : "Creating backup and applying changes…"}`)}`; const runToken = beginToolRun(output); try { const result = await window.cfbToolkit.runTool({ toolId, savePath: state.activeSave.path, mode, options }); if (!currentToolRun(output, runSave, runPage, runToken)) { await refreshHistory().catch(() => {}); return; } if (mode === "preview") state.genericPreviews.set(toolId, result); else { state.genericPreviews.delete(toolId); state.seasonLines = null; state.seasonLinesSave = null; state.seasonLinesError = null; } renderResult(output, result); if(toolId === "equipment-quickstart" && mode === "apply") await refreshQuickstartCounts(); await refreshHistory().catch(() => {}); } catch (error) { if (!currentToolRun(output, runSave, runPage, runToken)) return; const readable = readableError(error); if (/cached result|already been applied|save changed.*preview|source row.*changed|donor file changed/i.test(readable.message)) state.genericPreviews.delete(toolId); if (mode === "apply" && state.genericPreviews.get(toolId) === previous) renderResult(output, previous); showError(readable, output); markRunFailure(output, readable, mode); } finally { if (currentToolRun(output, runSave, runPage, runToken)) { document.querySelector("#preview").disabled = false; document.querySelector("#apply").disabled = !state.genericPreviews.has(toolId) || state.genericPreviews.get(toolId)?.details?.canApply === false; } } }
function summaryMetrics(result) { return `<div class="metric-grid">${result.summary.map(item => `<div class="metric"><strong>${escapeHtml(item.value)}</strong><small>${escapeHtml(item.label)}</small></div>`).join("")}</div>`; }
function previewChanges(result) { return [...(result.details?.changes ?? [])].map((value, index) => ({ value, index })).sort((a, b) => { const x = a.value, y = b.value; if (result.resultKind === "automatic-force-win") return Number(x.week) - Number(y.week) || String(x.awayTeam).localeCompare(String(y.awayTeam)) || String(x.homeTeam).localeCompare(String(y.homeTeam)) || a.index - b.index; return String(x.team ?? "").localeCompare(String(y.team ?? "")) || String(x.player ?? "").localeCompare(String(y.player ?? "")) || String(x.position ?? "").localeCompare(String(y.position ?? "")) || String(x.type ?? "").localeCompare(String(y.type ?? "")) || a.index - b.index; }).map(item => item.value); }
