function equipmentSkippedNotice(result) { if (result.resultKind !== "freshman-equipment") return ""; const details = result.details ?? {}, format = reasons => Object.entries(reasons ?? {}).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([reason, count]) => `${count.toLocaleString()} — ${escapeHtml(reason)}`).join("<br>"); const regular = Math.max(0,(details.reportedSkipped ?? details.skipped ?? 0)-(details.storageSkipped??0)), mod = details.modFcsSkipped ?? 0; return (regular ? `<div class="notice section"><strong>Why eligible players were skipped</strong><br>${format(details.reportedSkippedReasons ?? details.skippedReasons)}</div>` : "") + (mod ? `<details class="section"><summary>Mod-added FCS players left unchanged: ${mod.toLocaleString()}</summary><p>These additional FCS rosters are counted separately from the skipped-player total above. Their equipment remains protected. This does not indicate whether a mod is currently enabled.</p><p>${format(details.modFcsSkippedReasons)}</p></details>` : ""); }
function equipmentSafeguardNotice(result) {
  if (result.resultKind === "freshman-equipment") return helmetBalancePreview(result.details?.helmetBalance);
  if (result.resultKind !== "equipment-patcher") return "";
  const safeguards = result.details?.populationSafeguards, tattoos = result.details?.unlockedTattooPopulation, notes = [];
  for (const [cohortName, cohort] of safeguards?.scope === "team" ? [] : [["FBS", safeguards?.fbs], ["Directional FCS", safeguards?.fcs]]) {
    for (const [group, stats] of Object.entries(cohort?.visors ?? {})) if (stats.limited) notes.push(`${cohortName} visor assignments capped: ${group} prevalence reached ${(stats.ceiling * 100).toFixed(0)}%.`);
    for (const [group, stats] of Object.entries(cohort?.mouthpieces ?? {})) if (stats.limited) notes.push(`${cohortName} mouthpiece assignments capped: ${group} prevalence reached ${(stats.ceiling * 100).toFixed(0)}%. The cap limits new mouthpiece additions; existing mouthpieces are not removed.`);
    if (cohort?.undershirts?.limited) notes.push(`${cohortName} undershirt assignments capped: muscular/standard no-undershirt population reached the 5% floor.`);
  }
  if (tattoos?.scope === "team") {
    const above = tattoos.teams.filter(team => team.existingAboveCap).length;
    notes.push(`Tattoos: ${tattoos.addedTattooPlayers} added across ${tattoos.teams.length} teams. Each team has its own ${tattoos.capPercentage}% cap within your Player Pool; existing tattoos count first and are preserved.${above ? ` ${above} team(s) already exceeded their cap and received no additions.` : ""}`);
  } else if (tattoos) for (const [cohortName, cohort] of [["FBS", tattoos.fbs], ["Directional FCS", tattoos.fcs]]) {
    if (!cohort?.eligiblePlayers) continue;
    const percentage = (cohort.projectedPrevalence * 100).toFixed(1);
    notes.push(cohort.existingAboveCap
      ? `${cohortName} already has ${cohort.existingTattooPlayers} tattooed eligible players, above the ${cohort.capPercentage}% cap. Existing tattoos were preserved and no new tattoos were added.`
      : `${cohortName} tattoos: ${cohort.addedTattooPlayers} added; ${cohort.projectedTattooPlayers} of ${cohort.eligiblePlayers} eligible players projected (${percentage}%, ${cohort.capPercentage}% cap). Existing tattoos were preserved.`);
  }
  if (safeguards?.scope === "team" && (result.details?.visorFix || result.details?.unlockedMouthpieceFix || result.details?.rolledJerseyFix)) notes.push("Visor, mouthpiece and undershirt population safeguards apply separately to each team and position/body group. Existing gear is not removed to lower prevalence. Small limits round down to whole players.");
  const sortedTeams = teams => [...teams].sort((a, b) => a.team.localeCompare(b.team));
  const tattooAudit = tattoos?.scope === "team" && tattoos.teams.length ? `<details class="helmet-population-audit"><summary>Tattoo Frequencies by Team — Before / Limit / After</summary><div class="table-scroll"><table><thead><tr><th>Team</th><th>Eligible Players</th><th>Before</th><th>Limit</th><th>Added</th><th>After</th></tr></thead><tbody>${sortedTeams(tattoos.teams).map(team => `<tr><td>${escapeHtml(team.team)}</td><td>${team.eligiblePlayers}</td><td>${team.existingTattooPlayers}</td><td>${team.capCount} (${team.capPercentage}%)</td><td>${team.addedTattooPlayers}</td><td>${team.projectedTattooPlayers}${team.existingAboveCap ? " · Existing tattoos above cap" : ""}</td></tr>`).join("")}</tbody></table></div></details>` : "";
  const groupCounts = groups => Object.entries(groups).map(([group, stats]) => `${escapeHtml(localizedPosition(group))}: ${stats.equipped} / ${stats.ceilingCount}${stats.limited ? " (limit reached)" : ""}`).join(" · ") || "—";
  const showVisors = result.details?.visorFix, showMouthpieces = result.details?.unlockedMouthpieceFix;
  const gearAudit = safeguards?.scope === "team" && (showVisors || showMouthpieces) ? `<details class="helmet-population-audit"><summary>Equipment Frequencies by Team — Equipped / Limit</summary><div class="table-scroll"><table><thead><tr><th>Team</th>${showVisors ? "<th>Visors by Position Group</th>" : ""}${showMouthpieces ? "<th>Mouthpieces by Position Group</th>" : ""}</tr></thead><tbody>${sortedTeams(safeguards.teams).map(team => `<tr><td>${escapeHtml(team.team)}</td>${showVisors ? `<td>${groupCounts(team.visors)}</td>` : ""}${showMouthpieces ? `<td>${groupCounts(team.mouthpieces)}</td>` : ""}</tr>`).join("")}</tbody></table></div></details>` : "";
  return helmetPassPreview(result.details) + helmetBalancePreview(result.details?.helmetBalance) + (notes.length ? `<div class="notice section"><strong>Population safeguards</strong><br>${notes.map(escapeHtml).join("<br>")}</div>` : "") + tattooAudit + gearAudit;
}
