let historyOpenRequest=0;
function releaseSavedReviewArtwork(){for(const url of state.savedReview?.artworkUrls??[])URL.revokeObjectURL(url);state.savedReview=null;}
async function openHistoryRun(id) {
  const request=++historyOpenRequest,page=state.page,active=state.activeSave;

  const entry = state.history.find(item => item.id === id);
  if (!entry) return;
  if (state.page === "commentary-id" && !discardReviewAllowed()) return;
  captureToolSettings();
  if (entry.reviewAvailable) {
    try {
      const snapshot = await window.cfbToolkit.getReview(id);
      if(request!==historyOpenRequest||state.page!==page||state.activeSave!==active)return;
      if (snapshot) {
        const rows = snapshot.rows ?? snapshot.result?.details?.changes ?? [];
        const facets = snapshot.result?.details?.previewFacets ?? Object.fromEntries(["team", "position", "classYear"].map(field => [field, [...new Set(rows.map(row => String(row?.[field] ?? "")).filter(Boolean))] ]));
        releaseSavedReviewArtwork();const artworkUrls=new Set(),artwork=loadedArtwork(snapshot.dynastyArtwork,artworkUrls);
        state.savedReview = { entry, result: snapshot.result, rows, facets, query: "", filters: {},artwork,artworkUrls };
        state.commentaryReview = null;
        state.page = "saved-review";
        document.querySelectorAll("[data-page]").forEach(node => node.classList.toggle("active", node.dataset.page === "history"));
        render();
        return;
      }
    } catch (error) {if(request===historyOpenRequest&&state.page===page&&state.activeSave===active)showError(readableError(error));return; }
  }
  if (state.page !== "history") navigate("history");
  showHistory(id);
}
function seasonLinesPage() {
  const data = state.seasonLines, rows = data?.rows ?? [], weeks = [...new Set(rows.map(row => row.week))].sort((a, b) => a - b);
  return `<div class="tool-header"><div><div class="eyebrow">Dynasty Operations Center</div><h1>Season Matchup Lines</h1><p class="muted">Projected spread, moneyline, and over/under for this season's regular-season games. Viewing lines does not preview, apply, or record a Smart Force Win run.</p></div><button class="button secondary" id="back-to-home">← Home</button></div>${state.seasonLinesError ? `<div class="notice warning">${escapeHtml(state.seasonLinesError)}</div>` : ""}${!data ? state.seasonLinesError ? `<section class="card"><button class="button secondary" id="retry-season-lines">Try Again</button></section>` : `<section class="card">${toolLoading(`Reading this season's schedule and ratings…`)}</section>` : `<section class="season-lines-panel"><div class="season-lines-heading"><div><strong>Season ${escapeHtml(data.season)}</strong><span>${rows.length.toLocaleString()} ${rows.length === 1 ? "game" : "games"} with available projections</span></div><label>Matchup Model<select id="lines-model">${data.profiles.map(profile => `<option value="${escapeHtml(profile.value)}" ${profile.value === data.modelProfile ? "selected" : ""}>${escapeHtml(profile.label)}</option>`).join("")}</select></label></div><div class="season-lines-filters"><select id="lines-week" aria-label="Schedule Week">${weeks.map(week => `<option value="${week}">Week ${week}</option>`).join("")}</select><input class="input" id="lines-search" type="search" aria-label="Search Teams" placeholder="Search teams…"></div><div id="season-lines-games" class="season-lines-games"></div></section>`}`;
}
function seasonLineGameMarkup(row) {
  const spread=value=>Number.isFinite(value)?value===0?'PK':(value>0?'+':'')+value.toFixed(1):'—';
  const teamRow=(team,home)=>{
    const favorite=team===row.favorite,line=Number(row.favoriteSpread)*(favorite?1:-1),money=Number(favorite?row.favoriteMoneyline:row.underdogMoneyline),total=Number(row.total),rank=home?row.homeRank:row.awayRank;
    const teamLabel=(Number.isInteger(rank)&&rank>=1&&rank<=25?'#'+rank+' ':'')+team;
    return `<div class="season-line-team-row"><div class="season-line-team"><img data-team-logo src="${forceLogoUrl(team)}" alt=""><div><strong>${escapeHtml(teamLabel)}${home?'':`&nbsp;<span class="season-line-at">${row.neutral?'vs':'@'}</span>`}</strong></div></div><div class="season-line-tile" aria-label="${escapeHtml(team)} spread ${spread(line)}"><strong>${spread(line)}</strong></div><div class="season-line-tile" aria-label="${escapeHtml(team)} moneyline ${Number.isFinite(money)?forceMoneyline(money):'unavailable'}"><strong>${Number.isFinite(money)?forceMoneyline(money):'—'}</strong></div><div class="season-line-tile" aria-label="${home?'Under':'Over'} ${Number.isFinite(total)?total.toFixed(1):'unavailable'}"><strong><span>${home?'U':'O'}</span> ${Number.isFinite(total)?total.toFixed(1):'—'}</strong></div></div>`;
  };
  return `<article class="season-line-game" aria-label="${escapeHtml(row.awayTeam)} ${row.neutral?'versus':'at'} ${escapeHtml(row.homeTeam)}"><header class="season-line-market-head"><span>Week ${escapeHtml(row.week)}</span><span>Spread</span><span>Moneyline</span><span>Total</span></header>${teamRow(row.awayTeam,false)}${teamRow(row.homeTeam,true)}${row.rivalry?'<small class="season-line-note">Rivalry</small>':''}</article>`;
}
function paintSeasonLinesGames() {
  const data=state.seasonLines,target=document.querySelector('#season-lines-games');if(!data||!target)return;
  const week=Number(document.querySelector('#lines-week')?.value),query=(document.querySelector('#lines-search')?.value??'').trim().toLowerCase();
  const games=data.rows.filter(row=>row.week===week&&(!query||`${row.awayTeam} ${row.homeTeam}`.toLowerCase().includes(query)));
  target.innerHTML=games.length?games.map(seasonLineGameMarkup).join(''):'<div class="empty">No projected games match this week and search.</div>';
  bindTeamLogoFallbacks(target);
}

function renderSeasonLines() {
  content.innerHTML = seasonLinesPage();
  document.querySelector("#back-to-home")?.addEventListener("click", () => navigate("home"));
  document.querySelector("#retry-season-lines")?.addEventListener("click", () => loadSeasonLines());
  document.querySelector("#lines-model")?.addEventListener("change", event => loadSeasonLines(event.target.value));
  document.querySelector("#lines-week")?.addEventListener("change", paintSeasonLinesGames);
  document.querySelector("#lines-search")?.addEventListener("input", paintSeasonLinesGames);
  paintSeasonLinesGames();
}
async function loadSeasonLines(modelProfile) {
  const savePath = state.activeSave?.path;
  if (!savePath) return;
  const requestId = state.seasonLinesRequest = (state.seasonLinesRequest ?? 0) + 1;
  state.homeLinesLoading=false;
  const filters = { week: document.querySelector("#lines-week")?.value, search: document.querySelector("#lines-search")?.value ?? "" };
  state.seasonLines = null; state.seasonLinesError = null; renderSeasonLines();
  try {
    const data = await window.cfbToolkit.homeLines({ modelProfile });
    if (state.activeSave?.path !== savePath || state.seasonLinesRequest !== requestId) return;
    state.seasonLines = data; state.seasonLinesSave = savePath;
    if (state.page !== "season-lines") return;
    renderSeasonLines();
    const week = document.querySelector("#lines-week"), search = document.querySelector("#lines-search");
    if (week && [...week.options].some(option => option.value === filters.week)) week.value = filters.week;
    if (search) search.value = filters.search;
    paintSeasonLinesGames();
  } catch (error) { if (state.activeSave?.path === savePath && state.seasonLinesRequest === requestId) { state.seasonLinesError = readableError(error).message; if (state.page === "season-lines") renderSeasonLines(); } }
}

async function historyPage() { content.innerHTML = `<div class="tool-header"><div><div class="eyebrow">Activity</div><h1>Execution History</h1><p class="muted">Open a recent Preview or Apply run to revisit its review. Runs from older app versions still open their report and summary.</p></div></div><section class="card">${state.history.length ? activityRows(state.history) : `<div class="empty">No completed runs yet.</div>`}</section><section id="history-detail"></section>`; bindHistory(); }
function showHistory(id) { const entry = state.history.find(item => item.id === id); if (!entry) return; document.querySelector("#history-detail").innerHTML = `<section class="card section"><div class="tool-header"><div><h2>${escapeHtml(entry.toolName)}</h2><p class="muted">${formatDate(entry.timestamp)}${entry.appVersion ? ` · App v${escapeHtml(entry.appVersion.replace(/\.0$/, ""))}` : ""}</p></div><span class="version">${escapeHtml(entry.mode)} · ${escapeHtml(entry.status)}</span></div><p class="muted">This older run has no saved review panel. Its summary and report remain available.</p><p><strong>Input</strong><br><span class="muted">${escapeHtml(entry.inputPath)}</span></p>${summaryMetrics(entry)}${entry.backupPath ? `<p><strong>Backup</strong><br><span class="muted">${escapeHtml(entry.backupPath)}</span></p>` : ""}${entry.reportPath ? `<p><strong>Report</strong><br><span class="muted">${escapeHtml(entry.reportPath)}</span></p><button class="button secondary" data-open="${escapeHtml(entry.reportPath)}">Open Report</button>` : ""}</section>`; document.querySelector("#history-detail [data-open]")?.addEventListener("click", event => window.cfbToolkit.openPath(event.currentTarget.dataset.open)); }
async function reportsPage() {
  const request=state.reportsRequest=(state.reportsRequest??0)+1;
  const heading='<div class="tool-header"><div><div class="eyebrow">Library</div><h1>Reports</h1><p class="muted">Recent reports generated by Ace&#39;s CFB Toolkit.</p></div></div>';
  content.innerHTML=heading+`<section class="card">${toolLoading('Loading reports…')}</section>`;
  try{
    const reports=await window.cfbToolkit.listReports();if(state.page!=='reports'||state.reportsRequest!==request)return;
    content.innerHTML=heading+'<section class="card reports-library" id="reports-list"></section><div class="actions library-pagination"><button class="button secondary" id="reports-prev">Previous</button><span id="reports-count" role="status" aria-live="polite"></span><button class="button secondary" id="reports-next">Next</button></div>';
    let page=0;const draw=()=>{
      const shown=reports.slice(page*20,(page+1)*20);
      content.querySelector('#reports-list').innerHTML=shown.length?`<table class="reports-library-table"><thead><tr><th>Date</th><th>Tool</th><th>Report</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${shown.map(report=>`<tr><td>${formatDate(report.createdAt)}</td><td>${escapeHtml(report.tool)}</td><td class="report-library-name">${escapeHtml(report.name)}</td><td class="report-library-actions"><button class="button secondary" data-open="${escapeHtml(report.path)}">Open</button><button class="button secondary" data-reveal-report="${escapeHtml(report.path)}">Open File Location</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No reports yet.</div>';
      content.querySelector('#reports-count').textContent=`${reports.length?page*20+1:0}–${Math.min(reports.length,(page+1)*20)} of ${reports.length}`;
      content.querySelector('#reports-prev').disabled=page===0;content.querySelector('#reports-next').disabled=(page+1)*20>=reports.length;
      for(const button of content.querySelectorAll('[data-open],[data-reveal-report]'))button.addEventListener('click',()=>{
        const action=button.dataset.open?window.cfbToolkit.openPath(button.dataset.open):window.cfbToolkit.revealReport(button.dataset.revealReport);
        action.catch(error=>toast(readableError(error).message));
      });
    };
    content.querySelector('#reports-prev').onclick=()=>{page=Math.max(0,page-1);draw();};content.querySelector('#reports-next').onclick=()=>{page=Math.min(Math.max(0,Math.ceil(reports.length/20)-1),page+1);draw();};draw();
  }catch(error){if(state.page!=='reports'||state.reportsRequest!==request)return;content.innerHTML=heading+`<section class="card"><div class="notice warning">${escapeHtml(readableError(error).message)}</div><button class="button secondary" id="reports-retry">Try Again</button></section>`;content.querySelector('#reports-retry').onclick=reportsPage;}
}

function bindHistory() { document.querySelectorAll("[data-history-id]").forEach(button => button.addEventListener("click", () => openHistoryRun(button.dataset.historyId))); }
function bindCommon() { if(typeof beginOtherToolLoading === "function")beginOtherToolLoading(); document.querySelector("#select-save")?.addEventListener("click", chooseActiveSave); document.querySelector("#open-season-lines")?.addEventListener("click", () => { state.page = "season-lines"; render(); loadSeasonLines(); }); document.querySelector("#home-team-select")?.addEventListener("change", event => { state.selectedHomeTeam = event.target.value; render(); }); document.querySelector("#theme-select")?.addEventListener("change", async event => { const theme = event.target.value; document.documentElement.dataset.theme = theme; await window.cfbToolkit.updateTheme(theme); state.bootstrap.settings.theme = theme; applyAccentColor(state.bootstrap.settings); toast(`${theme === "light" ? "Light" : "Dark"} mode enabled`); }); bindMultiSelectEnhancements(); bindTeamPickers(); bindTeamLogoFallbacks(); bindStandardPreviewStage(); bindHistory(); bindSettingsArtwork(); bindConfigurationWindows(); if (state.page === "home") ensureHomeLines(); bindAccentSettings(); content.querySelectorAll("[data-open-tool]").forEach(button => button.addEventListener("click", () => navigate(button.dataset.openTool))); content.querySelectorAll("[data-home-page]").forEach(button => button.addEventListener("click", () => { if (button.dataset.artworkTeam) state.selectedArtworkTeam = button.dataset.artworkTeam; navigate(button.dataset.homePage); })); }
function bindRun(toolId) { document.querySelector("#preview")?.addEventListener("click", () => runTool(toolId, "preview")); document.querySelector("#apply")?.addEventListener("click", () => runTool(toolId, "apply")); if (["team-boost","nil-toggle","roster-generator","equipment-quickstart"].includes(toolId)) document.querySelectorAll(".standard-config-workspace input[id],.standard-config-workspace select[id]").forEach(input => input.addEventListener("change", () => { state.genericPreviews.delete(toolId); document.querySelector("#apply").disabled = true; })); }
function helpPage() {
  const sections=[["Start Here", "Choose a save, choose a tool, then review the changes before applying.", [["Preview and Apply", "Preview makes a list; it does not edit your save. Apply writes that exact list and creates a backup. If the save changes, build a new preview."], ["Best Practices / When to Run", "Run roster and equipment work in preseason when possible. Use Randomizer before Patcher. Team Boost is recommended after training results, but can technically be run anytime. Smart Force Win is best in Week 0."], ["Filters", "A player must match every filter you use. Empty selections usually mean all choices are allowed; check the label beside team selectors."], ["Settings and presets", "Save Settings keeps your choices for a tool. It does not apply them to the game save. A preset is a reusable set of choices."], ["Percentages", "Chance means a separate roll for each eligible player. A mix divides choices between styles or colors. A frequency also limits how common an item may be. These are different uses of percentages."], ["Fill to Frequency", "Try to reach your chosen share instead of just giving players a chance. Existing items count first. Protected players, outfit fit and available storage can keep the total below the target."]]], ["Jersey Renumber", "Give players suitable jersey numbers. Standard mode can share numbers between offense and defense; No Duplicates uses one of each number per team.", [["Player Locks", "Checked players keep their current number."], ["Retired Numbers", "Keep a number unavailable for new assignments. Unretire it if you want the tool to use it again."], ["Team Traditions", "Give a special number to the best player who matches your choices. Player locks and protections still apply."], ["Promotion Chances", "How often an eligible player tries for a more preferred number. 0% stops optional moves; it does not stop required corrections."], ["Personality", "A player style that affects number preferences. It does not change ratings or personality in the game."]]], ["Commentary IDs", "Help announcers say player names by matching them to the names the game can speak.", [["Exact and similar-sounding names", "Exact matches are straightforward. Review similar-sounding suggestions before accepting them; a close spelling may still sound wrong."], ["First-name fallback", "If the surname has no match, allow the tool to try the first name."], ["Keep unmatched players", "Keep their current commentary name when no match is found. Turning this off can clear the unmatched name."], ["Player protection", "Original EA roster players stay unchanged. Player filters choose which other players are checked."]]], ["Equipment Quickstart", "Choose your installed mods and let the tool build outfits and run its usual corrections.", [["Mods You Use", "Check only the mods you have installed. Unchecked mods do not supply new pool items."], ["Original EA players", "Leave protection on to preserve original EA roster players. Turn it off if you want them eligible too."], ["Player Memory", "Players successfully equipped by Quickstart or Randomizer are remembered for this dynasty, even if its filename changes. Clear Dynasty Memory to let them be randomized again; clearing memory does not undo equipment."], ["Donors", "The top 30 usable donors at each position supply outfit examples. Selected donor players keep their own outfits."]]], ["Equipment Randomizer", "Copy outfits from donor players, then optionally add selected accessories.", [["Donor selection", "Use the highest-rated donors or choose specific players. A donor file supplies examples and is not changed."], ["Cross-position mixing", "How often to borrow from the other positions you allow. For example, allow WR outfits for CBs."], ["Multiple-donor mixing", "Build one outfit from pieces of several donors. The two mixing chances share a 100% total; the remainder copies one donor."], ["Equipment pools", "Extra item rolls after donor copying. A category chance is a chance to add an allowed item, not a promise that every outfit will contain it. Item checkboxes choose the possible rolls."], ["No Drip", "One roll per player gives that player a simpler outfit by removing selected accessories. It is not a separate roll for each item. Every position has its own chance."], ["Pool restrictions", "New pool gloves, balaclavas, turtlenecks and string towels are excluded for OL, DT, K and P. Taped hands can roll for OL and DT. This rule does not remove donor-copied items. QBs use donor gloves only and keep at most one; when both hands have gloves, the throwing-hand glove is removed."]]], ["Equipment Patcher", "Choose the corrections you want, then configure only those corrections.", [["Helmets and facemasks", "Repair Only keeps helmets you allow and fixes the rest. Balance All also changes existing helmets to work toward your chosen mix. Facemasks must fit their helmet."], ["Visors and mouthpieces", "Set how common they should be. Existing items count. Reroll Existing Mouthpieces lets you change mouthpieces players already wear."], ["Colors and tape", "Choose the team mix or one fixed color. Match Player Accessory Color makes tape follow that player’s accessory color; the team tape mix chooses tape separately."], ["Cutoff pants", "Choose how common cutoff pants should be. Outfit adjustment can change the shirt and jersey to make them fit. Allow Leg Layers is optional and may cause clipping."], ["Tattoos", "Default: 30% with Fill to Frequency on. Existing sleeves and tattoos are preserved. Each team is capped separately. Japanese and Polynesian designs start unchecked. Placement settings decide arms, legs, or both for players receiving tattoos."], ["Remove Specific Items", "Choose the named items to remove from your filtered players. Helmets, facemasks, cleats, socks, pants and jersey styles cannot be removed."], ["Compatibility", "Fix supported outfit combinations that overlap or do not fit. Explicit item removal wins if a correction would otherwise add that item back."]]], ["Equipment Mapper", "Make your own replace, remove or assign rules using the equipment catalog.", [["Replace / Remove / Assign", "Replace swaps an existing item. Remove takes it off. Assign puts an item on matching players, even if they did not wear it before. Switching to Assign keeps the Existing Item you already picked."], ["Keep Current Colors", "Change the item, keep the player’s color. Example: replacing a black sleeve with a baggy sleeve gives a black baggy sleeve. Off uses the replacement color you selected. If no matching color exists, choose another replacement."], ["Only When Wearing", "Add a second requirement. Example: target outfits wearing a Relaxed Tee, then remove their turtleneck. Both items must be in the same outfit."], ["Both Sides", "Change both sides with one rule. Left and right can still use different items."], ["Matching items", "This Item matches the chosen piece. Any Color includes its other colors. Exact Configuration only matches the specific equipment setup you selected."], ["Warnings", "Known outfit clashes show a red warning. Apply Anyway lets you accept those appearance issues. Invalid data, conflicting rules and a changed save still block Apply."], ["Rule order", "Rules look at the original outfits. One rule does not create matches for another rule in the same run."]]], ["Roster Generator", "Replace selected teams with fictional players. Current strength, age and future potential are separate choices.", [["Caliber", "The target average player OVR for the roster. This is not the team OVR shown by the game, and individual players will vary."], ["Age and potential", "Age controls the class-year mix. Potential controls development and room to improve. A young team does not have to be weak or have high potential."], ["Position strength", "Decide where the team spends its talent. More share makes a group stronger. A group with more players needs more budget. Custom shares must total 100%."], ["Schemes and roster makeup", "Pick the offense and defense. Build to Scheme Needs can move roster spots between positions without changing the total number of players."], ["Individual teams", "Edit Team customizes one team. Save Team Settings keeps that draft and returns to the team list. Save All Team Settings keeps the whole window’s changes and closes it. Cancel discards changes made in the window."], ["Depth charts", "Reorder Depth Chart ranks the generated players for their roles. Play Now roster files need their depth charts reordered in-game."], ["What gets replaced", "This replaces players, including original EA roster players on the selected teams. Preview the roster and test a copied dynasty in-game."]]], ["Team Boost", "Raise or lower ratings on the teams and players you choose.", [["Rating choices", "Use position-relevant ratings for a broad boost, or pick specific attributes yourself. A player’s position matters, not only their archetype."], ["Adjustment range", "The tool picks an adjustment within your range. +2 to +5 raises ratings; negative values lower them. Game rating limits still apply."], ["Above / Below Average", "Compare players with teammates at the same position, not the entire team."], ["Position ranges", "Give selected positions their own range. Other positions use the main range."], ["Preview colors", "Green means a rating increased. Red means it decreased, regardless of your app accent color."]]], ["Long Snap Fixer", "Temporarily under construction.", [["Why it is paused", "A reported game issue links nonzero Long Snap ratings to field-goal accuracy. This tool is disabled while that is investigated."], ["Roster Generator", "Newly generated players use 0 Long Snap while the adjustment is paused."]]], ["NIL Toggle", "Change the in-game NIL flag for the players you choose.", [["True / False", "Choose whether the flag is on or off. It can affect in-game editing eligibility; it does not tell you whether someone is a real-life NIL player."], ["Player selection", "Use teams, positions, class years or individual players. Preview shows who matches and which flags actually need to change."]]], ["Dealbreaker Fixer", "Give eligible players a more useful mix of transfer dealbreakers.", [["Starting mix", "A bigger percentage makes that dealbreaker more likely. The player’s situation can change the final mix. None sets a minimum share without a dealbreaker."], ["Protections", "Protect players or existing dealbreaker types you want to keep. Original EA roster players stay unchanged."], ["Playing Style", "Use the position restriction if you only want Playing Style on supported positions. Fix Invalid Playing Style can replace existing values that do not fit."]]], ["Smart Force Win", "Choose which future games should receive force-win assignments.", [["What to do", "Evaluate builds a new set of suggestions. Clear Existing removes the assignments in the scope you choose. Always review Preview before Apply."], ["Games and weeks", "Choose the weeks to consider. Completed games and the active-week protection still apply."], ["User Schedule Only", "Check games involving your user-controlled teams. Opponents are still evaluated normally, but their other games are left out. Protect teams in Teams to Skip if you want their games left alone."], ["Protections", "Teams to Skip protects their entire matchup. Protected matchups and teams without reliable roster data are also left alone."], ["Matchup model", "Choose how ratings, coaches and home advantage affect the favorite. In Custom, increasing an influence makes it matter more. Model weights in a group must add up to 100% when requested."], ["Weekly limit", "The most new force wins to add each week. 0 means no limit. It does not clear existing assignments."], ["Season lines", "Projected lines help compare matchups. Viewing them does not force any game result."]]], ["History, Reports and Settings", "Review earlier work and personalize the app.", [["History and reports", "History records runs for this dynasty, including renamed copies. Reports contain the full player-by-player detail. An old preview is a record, not a new Apply."], ["App colors", "Accent Color changes buttons and highlights. Main Color tints dark surfaces; light-mode backgrounds stay neutral."], ["Team artwork", "Custom artwork belongs to the dynasty, including its renamed saves and copies."], ["Export and import presets", "Export saves your tool choices in a file. Import brings those choices into the preset list; it does not run a tool or edit a dynasty."], ["Save as My Default", "Use your preferred settings when you first open this tool. A default changes tool choices, not the game save."], ["Updates", "The update notice shows what changed in the new release."]]]];
  return `<div class="tool-header"><div><div class="eyebrow">Help & Instructions</div><h1>How to Use the Toolkit</h1><p class="muted">Choose a tool below. Each explanation starts with what changes and gives examples where they help.</p></div></div><div class="configuration-stack help-reference">${sections.map(([title,intro,rows],index)=>`<details class="card help-topic" data-help-topic="${escapeHtml(title)}" ${index===0?'open':''}><summary><strong>${escapeHtml(title)}</strong></summary><p>${escapeHtml(intro)}</p><dl>${rows.map(([name,text])=>`<dt><strong>${escapeHtml(name)}</strong></dt><dd>${escapeHtml(text)}</dd>`).join('')}</dl></details>`).join('')}</div>`;
}

function settingsPage() {
  const teams = state.homeContext?.teams ?? [], selected = teams.find(team => team.name === state.selectedArtworkTeam) ?? teams[0], artwork = selected ? state.artwork[selected.name.trim().toLowerCase()] ?? {} : {};
  return `<div class="tool-header"><div><div class="eyebrow">Application</div><h1>Settings</h1></div></div><section class="card"><h2>Appearance</h2><label for="theme-select">Theme</label><select id="theme-select"><option value="light" ${state.bootstrap.settings.theme === "light" ? "selected" : ""}>Light</option><option value="dark" ${state.bootstrap.settings.theme === "dark" ? "selected" : ""}>Dark</option></select><label for="accent-color"><strong>Accent Color</strong></label><div class="accent-settings"><input id="accent-color" type="color" value="${escapeHtml(state.bootstrap.settings.accentColor ?? "#087a45")}" aria-label="Choose app accent color"><span id="accent-color-label">${escapeHtml(state.bootstrap.settings.accentColor ?? "Default green")}</span><button type="button" class="button secondary" id="accent-reset">Default Green</button></div><p class="muted" data-option-explanation>Choose your own accent color for buttons, highlights, and navigation. Colors adjust for readability in light and dark mode. Team logos and equipment colors do not change.</p><label for="base-color"><strong>Main Color</strong></label><div class="accent-settings"><input id="base-color" type="color" value="${escapeHtml(state.bootstrap.settings.baseColor??"#808080")}" aria-label="Choose main app color"><span id="base-color-label">${escapeHtml(state.bootstrap.settings.baseColor??"Neutral")}</span><button type="button" class="button secondary" id="base-reset">Neutral</button></div><p class="muted" data-option-explanation>Tint the dark areas, including the sidebar and top bar. Dark mode also tints panels and the page background; light mode keeps them neutral. The accent color stays separate.</p><div class="configuration-entry"><div><strong>Team Artwork</strong><p id="artwork-summary">${Object.keys(state.artwork).length} teams with custom artwork · Defaults are used everywhere else.</p></div><button type="button" class="button secondary" id="configure-team-artwork" ${teams.length&&ToolkitDynastyIdentity.validDynastyId(state.activeSave?.dynastyId) ? "" : "disabled"}>Manage Artwork</button></div>${state.homeContext?.legacyArtworkAvailable?'<div class="configuration-entry"><div><strong>Previous Team Artwork</strong><p>Earlier artwork was shared across dynasties. Choose this dynasty to keep using it here.</p></div><button class="button secondary" id="import-legacy-artwork">Use for This Dynasty</button></div>':''}<p class="muted" data-option-explanation>Custom logos and headers belong to this dynasty, including its renamed saves and copies. Other dynasties have their own artwork. Images stay on this computer.</p><div class="settings-section-heading">Active Save</div><p class="muted">${escapeHtml(state.activeSave?.path || "No save selected")}</p><div class="actions"><button class="button secondary" id="select-save">Change Save</button></div><p class="section muted" data-option-explanation>Theme, custom team artwork, and window size are remembered. Active Dynasty starts empty each time the app launches.</p></section>${window.toolkitUpdates?.settings() ?? ""}`;
}
function bindSettingsArtwork() {
  const launch=document.querySelector('#configure-team-artwork');
  if(launch&&launch.dataset.bound!=='true'){launch.dataset.bound='true';launch.addEventListener('click',openTeamArtworkEditor);}
  document.querySelector('#import-legacy-artwork')?.addEventListener('click',async()=>{
    const active=state.activeSave;
    try{await window.cfbToolkit.importLegacyTeamArtwork({dynastyId:active?.dynastyId});if(state.activeSave!==active)return;await refreshHomeContext();if(state.activeSave===active){render();toast('Previous artwork added to this dynasty.');}}
    catch(error){if(state.activeSave===active)toast(readableError(error).message);}
  });
  document.querySelector('#settings-artwork-search')?.addEventListener('input',event=>{const query=event.target.value.trim().toLowerCase();document.querySelectorAll('[data-artwork-team-choice]').forEach(button=>button.hidden=!button.dataset.artworkTeamChoice.toLowerCase().includes(query));});
  document.querySelectorAll('[data-artwork-team-choice]').forEach(button=>button.addEventListener('click',()=>{state.selectedArtworkTeam=button.dataset.artworkTeamChoice;refreshSettingsArtwork();}));
  document.querySelector('#settings-artwork-team')?.addEventListener('change',event=>{state.selectedArtworkTeam=event.target.value;refreshSettingsArtwork();});
  for(const button of document.querySelectorAll('[data-artwork-upload],[data-artwork-clear]'))button.addEventListener('click',async()=>{
    const active=state.activeSave,upload=Boolean(button.dataset.artworkUpload),kind=button.dataset.artworkUpload??button.dataset.artworkClear,teamName=document.getElementById('settings-artwork-team')?.value;
    button.disabled=true;
    try{
      const result=await window.cfbToolkit[upload?'chooseTeamArtwork':'clearTeamArtwork']({teamName,kind,dynastyId:active?.dynastyId});
      if(!result||state.activeSave!==active||result.dynastyId!==active.dynastyId)return;
      const key=teamName.trim().toLowerCase(),entry=state.artwork[key]??={};
      if(entry[kind]){URL.revokeObjectURL(entry[kind]);state.artworkUrls.delete(entry[kind]);delete entry[kind];}
      if(upload)entry[kind]=artworkObjectUrl(result.image);
      if(!Object.keys(entry).length)delete state.artwork[key];
      refreshSettingsArtwork();toast(upload?`${kind==='logo'?'Logo':'Header'} updated for ${teamName}`:`Default ${kind} restored for ${teamName}`);
    }catch(error){if(state.activeSave===active)showError(readableError(error));}
    finally{if(button.isConnected)button.disabled=false;}
  });
}

function render() {
  closeConfigurationDialogs();
  if(state.saveLoading){content.innerHTML=saveLoadingPage();return;}
  if (state.page === "home") content.innerHTML = homePage();
  else if (state.page === "saved-review") { renderSavedReview(); return; }
  else if (state.page === "season-lines") { renderSeasonLines(); return; }
  else if (state.page === "help") content.innerHTML = helpPage();
  else if (state.page === "history") { historyPage(); return; }
  else if (state.page === "reports") { reportsPage(); return; }
  else if (state.page === "settings") content.innerHTML = settingsPage();
  else if (state.page === "about") content.innerHTML = `<div class="hero"><div class="eyebrow">About</div><h1>Ace&#39;s CFB Toolkit</h1><p class="muted">Version ${escapeHtml(state.bootstrap.app.version)} · Supported schemas ${escapeHtml(state.bootstrap.app.schemas.join(", "))}</p><p>Manage your dynasty with clear previews, detailed reports, and backups before changes are applied.</p><p>Ace&#39;s CFB Toolkit is open source. You are free to copy, modify, reuse, or incorporate its tools and code into your own projects.</p><p><a href="https://github.com/ArtVsTheWorld/Aces-CFB-Toolkit" target="_blank" rel="noopener noreferrer">View the source code on GitHub →</a></p></div>`;
  else { const tool = state.bootstrap.registry.tools.find(item => item.id === state.page); if (tool?.id === "equipment-quickstart" && tool.status === "available") { equipmentQuickstartPage(tool); return; } if (tool?.id === "equipment-mapper" && tool.status === "available") { equipmentMapperPage(tool); return; } if (tool?.id === "roster-generator" && tool.status === "available") { rosterGeneratorPage(tool); return; } if (tool?.id === "nil-toggle" && tool.status === "available") { nilTogglePage(tool); return; } if (tool?.id === "team-boost" && tool.status === "available") { teamBoostPage(tool); return; } if (tool?.id === "jersey-renumber" && tool.status === "available") { jerseyPage(tool); return; } if (["freshman-equipment", "equipment-patcher"].includes(tool?.id) && tool.status === "available") { equipmentPage(tool); return; } if (tool?.id === "automatic-force-win" && tool.status === "available") { forceWinPage(tool); return; } if (tool?.id === "dealbreaker-fixer" && tool.status === "available") { dealbreakerPage(tool); return; } if (tool?.id === "commentary-id" && tool.status === "available") content.innerHTML = state.commentaryReview ? commentaryReviewPage(tool) : commentaryConfigPage(tool); else content.innerHTML = tool?.id === "long-snap" && tool.status === "available" ? longSnapPage(tool) : plannedTool(tool); }
  bindCommon(); if (state.page === "long-snap") bindRun("long-snap"); if (state.page === "commentary-id") { if (state.commentaryReview) { bindCommentaryReview(); bindCommentaryReviewFilters(); if (state.commentaryReview.autoSkipped) { showStandardPreviewStage(true); if (state.commentaryReview.lastResult) { renderResult(document.querySelector("#run-output"), state.commentaryReview.lastResult); document.querySelector("#commentary-apply").disabled = state.commentaryReview.lastResult.mode !== "preview"; } } } else bindCommentaryConfig(); }
}

document.querySelector("#change-save").addEventListener("click", chooseActiveSave);
document.querySelector("#sidebar-toggle").addEventListener("click", event => { document.body.classList.toggle("sidebar-collapsed"); event.currentTarget.setAttribute("aria-expanded", String(!document.body.classList.contains("sidebar-collapsed"))); });
window.cfbToolkit.bootstrap().then(async snapshot => { state.bootstrap = snapshot; document.documentElement.dataset.theme = snapshot.settings.theme === "dark" ? "dark" : "light"; applyAccentColor(snapshot.settings); document.querySelectorAll("#app-version,#topbar-app-version").forEach(label => label.textContent = `v${snapshot.app.version}`); state.activeSave = snapshot.activeSave; await refreshHistory(); buildNavigation(); updateActiveSave(); render(); }).catch(error => showError(readableError(error))).finally(() => document.querySelector("#startup-screen")?.remove());

window.cfbToolkit.onDynastyProfilesChanged?.(async()=>{
  const active=state.activeSave,page=state.page;
  await refreshHistory().catch(()=>{});
  if(state.saveLoading||state.activeSave!==active)return;
  if(page==='history'&&state.page===page)historyPage();
  if(page==='home'&&state.page===page&&!document.querySelector('dialog[open]')){
    await refreshHomeContext({when:()=>!state.saveLoading&&state.page===page&&!document.querySelector('dialog[open]')});
    if(!state.saveLoading&&state.activeSave===active&&state.page===page&&!document.querySelector('dialog[open]'))render();
  }
});
